local function _run()
    local s = table.concat(_D)
    _D = nil
    local map = {}
    for i = 1, 16 do map[string.byte(_A, i)] = i - 1 end
    local n, kn = math.floor(#s / 2), #_K
    local out, buf, bn = {}, {}, 0
    for i = 1, n do
        local b = map[string.byte(s, 2 * i - 1)] * 16 + map[string.byte(s, 2 * i)]
        local m = (i * 7 + math.floor(i / 256) * 13) % 256
        buf[bn + 1] = string.char(_x(_x(b, _K[(i - 1) % kn + 1]), m))
        bn = bn + 1
        if bn >= 4096 then out[#out + 1] = table.concat(buf, "", 1, bn); bn = 0 end
    end
    if bn > 0 then out[#out + 1] = table.concat(buf, "", 1, bn) end
    local f, err = loadstring(table.concat(out))
    if not f then warn("[loader] " .. tostring(err)) return end
    return f()
end
return _run()
